#pragma once

#include "DistrhoPlugin.hpp"

/**
 * OctofilterPlugin — Phase 0 pass-through skeleton.
 *
 * Audio flows straight from input to output with no processing.
 * This verifies that DPF builds, loads in a DAW, and passes audio
 * before any DSP is added.
 */
class OctofilterPlugin : public DISTRHO::Plugin
{
public:
    OctofilterPlugin();

protected:
    // ── Info ──────────────────────────────────────────────────────────────
    const char* getLabel()   const override { return "Octofilter"; }
    const char* getMaker()   const override { return "Henry"; }
    const char* getLicense() const override { return "Proprietary"; }
    uint32_t    getVersion() const override { return d_version(0, 1, 0); }
    int64_t     getUniqueId() const override
    {
        // Unique 4-char code — change before release if needed.
        return d_cconst('O', 'c', 't', 'o');
    }

    // ── Init ──────────────────────────────────────────────────────────────
    void initParameter(uint32_t index, DISTRHO::Parameter& parameter) override;

    // ── State ─────────────────────────────────────────────────────────────
    float getParameterValue(uint32_t index) const override;
    void  setParameterValue(uint32_t index, float value) override;

    // ── Process ───────────────────────────────────────────────────────────
    void run(const float** inputs, float** outputs,
             uint32_t frames) override;

private:
    // Placeholder parameter value (wet/dry, 0–1, default 1 = fully wet).
    float fWetDry { 1.0f };

    DISTRHO_DECLARE_NON_COPYABLE_WITH_LEAK_DETECTOR(OctofilterPlugin)
};

