#include "OctofilterPlugin.hpp"

// ── DPF plugin descriptor ─────────────────────────────────────────────────
// These macros tell DPF the I/O layout and that we have no MIDI or UI yet.
START_NAMESPACE_DISTRHO

// 1 parameter for now (Wet/Dry); will grow in Phase 4.
static constexpr uint32_t kParameterCount = 1;

enum Parameters {
    kParamWetDry = 0
};

// ── Constructor ──────────────────────────────────────────────────────────────
OctofilterPlugin::OctofilterPlugin()
    : DISTRHO::Plugin(kParameterCount, 0 /* programs */, 0 /* states */)
{
}

// ── initParameter ────────────────────────────────────────────────────────────
void OctofilterPlugin::initParameter(uint32_t index, DISTRHO::Parameter& param)
{
    switch (index)
    {
    case kParamWetDry:
        param.name       = "Wet/Dry";
        param.symbol     = "wet_dry";
        param.unit       = "%";
        param.ranges.min = 0.0f;
        param.ranges.max = 1.0f;
        param.ranges.def = 1.0f;
        param.hints      = kParameterIsAutomatable;
        break;
    default:
        break;
    }
}

// ── getParameterValue / setParameterValue ────────────────────────────────────
float OctofilterPlugin::getParameterValue(uint32_t index) const
{
    switch (index)
    {
    case kParamWetDry: return fWetDry;
    default:           return 0.0f;
    }
}

void OctofilterPlugin::setParameterValue(uint32_t index, float value)
{
    switch (index)
    {
    case kParamWetDry: fWetDry = value; break;
    default:           break;
    }
}

// ── run (audio callback) ─────────────────────────────────────────────────────
void OctofilterPlugin::run(const float** inputs, float** outputs,
                           uint32_t frames)
{
    // Phase 0: pure pass-through — copy input directly to output.
    // Stereo: channel 0 = left, channel 1 = right.
    const float* inL  = inputs[0];
    const float* inR  = inputs[1];
    float*       outL = outputs[0];
    float*       outR = outputs[1];

    for (uint32_t i = 0; i < frames; ++i)
    {
        outL[i] = inL[i];
        outR[i] = inR[i];
    }
}

// ── DPF plugin entry point ────────────────────────────────────────────────────
Plugin* createPlugin()
{
    return new OctofilterPlugin();
}

END_NAMESPACE_DISTRHO

