static constexpr int kMaxPoints = 8;

/**
 * PointState — all per-point data owned in one place.
 *
 * Each of the 2–8 filter points has one PointState. The plugin
 * maintains an array of kMaxPoints of these; only the first
 * activePointCount are processed.
 */
struct PointState
{
    // ── DSP components ────────────────────────────────────────────────────
    BiQuadFilter filter;

    // ── Parameters ────────────────────────────────────────────────────────

    /** Filter type, mirrors BiQuadFilter::Type */
    BiQuadFilter::Type filterType { BiQuadFilter::Type::LowPass };

    /**
     * Randomised semitone offset applied on top of the global Texture
     * frequency. Range roughly ±24 semitones; set by randomise().
     */
    float cutoffOffsetSemitones { 0.0f };

    /**
     * Pan position in [-1, 1].
     * -1 = hard left, 0 = centre, +1 = hard right.
     */
    float pan { 0.0f };

    /** Per-point output gain, 0–2 (0–200%). Default 1. */
    float level { 1.0f };

    /** Feedback send amount for this point, 0–1. */
    float feedbackAmount { 0.0f };

    /** Pitch shift in semitones for this point's feedback path, ±24. */
    float pitchShiftSemitones { 0.0f };

    /**
     * Source channel index for this point.
     * 0 = left, 1 = right, set by InputRouter.
     * -1 = use equal L+R mix (centre point in odd configs).
     */
    int sourceChannel { 0 };

    // ── Helpers ───────────────────────────────────────────────────────────

    /** Re-apply current filter type and cutoff to the biquad. */
    void applyFilterParams(float cutoffHz, float q) noexcept
    {
        filter.setType(filterType);
        filter.setCutoff(cutoffHz);
        filter.setQ(q);
    }

    /** Reset DSP state (e.g. on transport restart). */
    void reset() noexcept { filter.reset(); }
};

} // namespace Octofilter

