#include "OctofilterPlugin.hpp"
#include <cmath>
#include <cstring>

START_NAMESPACE_DISTRHO

// ── Parameter indices ─────────────────────────────────────────────────────────
enum Parameters : uint32_t
{
    kParamPointCount = 0,
    kParamTexture,
    kParamSpread,
    kParamResonance,
    kParamWetDry,
    kParamCount
};

// ── Constructor ──────────────────────────────────────────────────────────────
OctofilterPlugin::OctofilterPlugin()
    : Plugin(kParamCount, 0 /* programs */, 0 /* states */)
{
    rebuildRouting();
    updateFilterParams();
}

// ── sampleRateChanged ────────────────────────────────────────────────────────
void OctofilterPlugin::sampleRateChanged(double newSampleRate)
{
    mSampleRate = newSampleRate;
    for (int i = 0; i < Octofilter::kMaxPoints; ++i)
        mPoints[i].filter.setSampleRate(newSampleRate);
    updateFilterParams();
}

// ── initParameter ────────────────────────────────────────────────────────────
void OctofilterPlugin::initParameter(uint32_t index, Parameter& param)
{
    switch (index)
    {
    case kParamPointCount:
        param.name       = "Point Count";
        param.symbol     = "point_count";
        param.unit       = "";
        param.ranges.min = 2.0f;
        param.ranges.max = 8.0f;
        param.ranges.def = 4.0f;
        param.hints      = kParameterIsAutomatable | kParameterIsInteger;
        break;

    case kParamTexture:
        param.name       = "Texture";
        param.symbol     = "texture";
        param.unit       = "";
        param.ranges.min = 0.0f;
        param.ranges.max = 1.0f;
        param.ranges.def = 0.5f;
        param.hints      = kParameterIsAutomatable;
        break;

    case kParamSpread:
        param.name       = "Spread";
        param.symbol     = "spread";
        param.unit       = "";
        param.ranges.min = 0.0f;
        param.ranges.max = 1.0f;
        param.ranges.def = 1.0f;
        param.hints      = kParameterIsAutomatable;
        break;

    case kParamResonance:
        param.name       = "Resonance";
        param.symbol     = "resonance";
        param.unit       = "";
        param.ranges.min = 0.1f;
        param.ranges.max = 20.0f;
        param.ranges.def = 0.707f;
        param.hints      = kParameterIsAutomatable;
        break;

    case kParamWetDry:
        param.name       = "Wet/Dry";
        param.symbol     = "wet_dry";
        param.unit       = "";
        param.ranges.min = 0.0f;
        param.ranges.max = 1.0f;
        param.ranges.def = 1.0f;
        param.hints      = kParameterIsAutomatable;
        break;

    default:
        break;
    }
}

// ── getParameterValue ────────────────────────────────────────────────────────
float OctofilterPlugin::getParameterValue(uint32_t index) const
{
    switch (index)
    {
    case kParamPointCount: return static_cast<float>(mActivePoints);
    case kParamTexture:    return mTexture;
    case kParamSpread:     return mSpread;
    case kParamResonance:  return mResonance;
    case kParamWetDry:     return mWetDry;
    default:               return 0.0f;
    }
}

// ── setParameterValue ────────────────────────────────────────────────────────
void OctofilterPlugin::setParameterValue(uint32_t index, float value)
{
    switch (index)
    {
    case kParamPointCount:
    {
        const int n = static_cast<int>(value + 0.5f);
        mActivePoints = (n < 2) ? 2 : (n > 8) ? 8 : n;
        rebuildRouting();
        updateFilterParams();
        break;
    }
    case kParamTexture:
        mTexture = value;
        updateFilterParams();
        break;

    case kParamSpread:
        mSpread = value;
        rebuildRouting(); // spread changes pan positions
        break;

    case kParamResonance:
        mResonance = value;
        updateFilterParams();
        break;

    case kParamWetDry:
        mWetDry = value;
        break;

    default:
        break;
    }
}

// ── run (audio callback) ─────────────────────────────────────────────────────
void OctofilterPlugin::run(const float** inputs, float** outputs,
                           uint32_t frames)
{
    const int   numInputs = (DISTRHO_PLUGIN_NUM_INPUTS >= 2) ? 2 : 1;
    float*      outL      = outputs[0];
    float*      outR      = outputs[1];

    for (uint32_t f = 0; f < frames; ++f)
    {
        float wetL = 0.0f, wetR = 0.0f;

        for (int p = 0; p < mActivePoints; ++p)
        {
            Octofilter::PointState& pt = mPoints[p];

            // 1. Route input sample to this point
            const float inSample =
                Octofilter::InputRouter::getSample(inputs, f, pt, numInputs);

            // 2. Filter
            const float filtered = pt.filter.process(inSample);

            // 3. Apply point level
            const float scaled = filtered * pt.level;

            // 4. Accumulate into stereo bus with pan law
            Octofilter::StereoMixer::accumulate(scaled, pt.pan, wetL, wetR);
        }

        // 5. Dry/wet mix
        const float dryL = inputs[0][f];
        const float dryR = (numInputs > 1) ? inputs[1][f] : inputs[0][f];

        outL[f] = dryL + mWetDry * (wetL - dryL);
        outR[f] = dryR + mWetDry * (wetR - dryR);
    }
}

// ── Private helpers ───────────────────────────────────────────────────────────

void OctofilterPlugin::rebuildRouting() noexcept
{
    // Assign L/R/mix channels to each point
    const int numInputs = DISTRHO_PLUGIN_NUM_INPUTS;
    Octofilter::InputRouter::assign(mPoints, mActivePoints, numInputs);

    // Spread pan positions evenly across [-spread, +spread]
    for (int i = 0; i < mActivePoints; ++i)
    {
        if (mActivePoints == 1)
        {
            mPoints[i].pan = 0.0f;
        }
        else
        {
            // Evenly spaced from -mSpread to +mSpread
            const float t   = static_cast<float>(i) / static_cast<float>(mActivePoints - 1);
            mPoints[i].pan  = (t * 2.0f - 1.0f) * mSpread;
        }
    }
}

void OctofilterPlugin::updateFilterParams() noexcept
{
    for (int i = 0; i < mActivePoints; ++i)
    {
        Octofilter::PointState& pt = mPoints[i];
        const float cutoff = Octofilter::TextureMapper::computeCutoff(
            mTexture, pt.cutoffOffsetSemitones);
        pt.applyFilterParams(cutoff, mResonance);
    }
}

// ── DPF entry point ───────────────────────────────────────────────────────────
Plugin* createPlugin()
{
    return new OctofilterPlugin();
}

END_NAMESPACE_DISTRHO

