/**
 * Process one sample. Returns the gain-reduced output.
 * Also writes the applied gain to `gainOut` (useful for metering/debug).
 */
float process(float x, float* gainOut = nullptr) noexcept
{
    // 1. Write input into lookahead delay
    mDelayBuf[mWritePos] = x;

    // 2. Read the delayed sample that is about to emerge
    const int readPos   = (mWritePos - mLookaheadSize + kMaxBufSize) % kMaxBufSize;
    const float delayed = mDelayBuf[readPos];

    // 3. Advance write position
    mWritePos = (mWritePos + 1) % kMaxBufSize;

    // 4. Find the peak across the entire lookahead window.
    //    This ensures the gain is reduced BEFORE the peak reaches the output.
    float peakInWindow = 0.0f;
    for (int i = 0; i < mLookaheadSize; ++i)
    {
        const int idx = (mWritePos - 1 - i + kMaxBufSize) % kMaxBufSize;
        const float a = std::fabs(mDelayBuf[idx]);
        if (a > peakInWindow) peakInWindow = a;
    }

    // 5. Compute required gain to bring the window peak below ceiling
    float targetGain = 1.0f;
    if (peakInWindow > kCeiling)
        targetGain = kCeiling / peakInWindow;

    // 6. Envelope: instant attack (snap down), smooth release
    if (targetGain < mGainEnv)
        mGainEnv = targetGain;
    else
        mGainEnv = 1.0f - mReleaseCoeff * (1.0f - mGainEnv);

    if (mGainEnv < 0.0f) mGainEnv = 0.0f;
    if (mGainEnv > 1.0f) mGainEnv = 1.0f;

    if (gainOut) *gainOut = mGainEnv;

    return delayed * mGainEnv;
}

