#pragma once

#include "IPitchShifter.hpp"
#include "pffft.h"

#include <cmath>
#include <cstring>
#include <cstdlib>

namespace Octofilter
{

/**
 * PhaseVocoderShifter — real-time phase vocoder pitch shifter.
 *
 * Algorithm overview:
 *   1. Accumulate input into an overlap-add buffer.
 *   2. Every hopSize samples, copy a windowSize frame, apply Hann window,
 *      forward FFT.
 *   3. Compute instantaneous frequency for each bin via phase difference.
 *   4. Stretch the frequency axis by the pitch ratio (resample bins).
 *      Phase locking: each bin's phase is anchored to its nearest peak bin,
 *      preserving transient/harmonic relationships and reducing phasiness.
 *   5. Inverse FFT, apply synthesis Hann window, overlap-add to output.
 *   6. Output is read from the OLA buffer with a hopSize-sample stride.
 *
 * Latency = windowSize samples (one analysis frame).
 *
 * All buffers allocated in prepare() — zero RT allocations.
 */
class PhaseVocoderShifter final : public IPitchShifter
{
public:
    // Default window size — 512 samples (~11 ms @ 44.1 kHz), good for feedback.
    static constexpr int kDefaultWindowSize = 512;
    static constexpr int kOverlapFactor     = 4;    // 4× overlap
    static constexpr int kMaxWindowSize     = 2048; // high-quality mode cap

    PhaseVocoderShifter() = default;

    ~PhaseVocoderShifter() override
    {
        freeBuffers();
    }

    // ── IPitchShifter ─────────────────────────────────────────────────────

    void prepare(double sampleRate, int /*maxBlockSize*/) override
    {
        mSampleRate  = static_cast<float>(sampleRate);
        mWindowSize  = kDefaultWindowSize;
        mHopSize     = mWindowSize / kOverlapFactor;
        mNumBins     = mWindowSize / 2 + 1;
        mOlaScale    = 1.0f / (static_cast<float>(kOverlapFactor) * 0.5f);

        freeBuffers();
        allocBuffers();
        buildWindow();
        reset();
    }

    void setShift(float semitones) override
    {
        // Clamp to ±24 semitones
        if (semitones >  24.0f) semitones =  24.0f;
        if (semitones < -24.0f) semitones = -24.0f;
        mPitchRatio = std::pow(2.0f, semitones / 12.0f);
    }

    void reset() override
    {
        if (!mReady) return;

        std::memset(mInputBuf,    0, mWindowSize * sizeof(float));
        std::memset(mOutputBuf,   0, mWindowSize * sizeof(float));
        std::memset(mFftBuf,      0, mWindowSize * sizeof(float));
        std::memset(mFftWork,     0, mWindowSize * sizeof(float));
        std::memset(mLastPhaseIn, 0, mNumBins    * sizeof(float));
        std::memset(mSumPhaseOut, 0, mNumBins    * sizeof(float));
        std::memset(mOutputAccum, 0, (mWindowSize + mHopSize) * sizeof(float));

        mInputFill    = 0;
        mOutputReady  = 0;
    }

    int getLatencySamples() const override { return mWindowSize; }

    void process(const float* in, float* out, int numSamples) override
    {
        for (int i = 0; i < numSamples; ++i)
        {
            // Push one sample into the input ring
            mInputBuf[mInputFill++] = in[i];

            // When we have a full hop, run the vocoder
            if (mInputFill >= mHopSize)
            {
                processFrame();
                mInputFill = 0;
            }

            // Read one sample from the output accum
            out[i] = mOutputReady > 0 ? mOutputAccum[0] : 0.0f;

            // Shift output accum left by one (ring buffer would be faster,
            // but this keeps indexing simple and numSamples is typically small)
            if (mOutputReady > 0)
            {
                std::memmove(mOutputAccum, mOutputAccum + 1,
                             (mWindowSize + mHopSize - 1) * sizeof(float));
                mOutputAccum[mWindowSize + mHopSize - 1] = 0.0f;
                --mOutputReady;
            }
        }
    }

private:
    // ── Frame processing ──────────────────────────────────────────────────

    void processFrame() noexcept
    {
        // --- Analysis ---

        // Copy latest windowSize samples from input ring into FFT buffer
        // and apply analysis Hann window
        for (int k = 0; k < mWindowSize; ++k)
        {
            // mInputBuf holds the last mHopSize new samples; prepend from
            // the saved overlap (mFftBuf acts as the overlap store here)
            // We use a two-part copy from the saved frame + new samples.
            // Simpler: treat mInputBuf as a FIFO topped up by mHopSize each call.
            // The saved overlap is in mAnalysisFrame.
        }

        // Shift analysis frame left by hopSize and insert new samples
        std::memmove(mAnalysisFrame, mAnalysisFrame + mHopSize,
                     (mWindowSize - mHopSize) * sizeof(float));
        std::memcpy(mAnalysisFrame + mWindowSize - mHopSize,
                    mInputBuf, mHopSize * sizeof(float));

        // Apply Hann window
        for (int k = 0; k < mWindowSize; ++k)
            mFftBuf[k] = mAnalysisFrame[k] * mWindow[k];

        // Forward FFT (in-place, ordered output)
        pffft_transform_ordered(mPffftSetup, mFftBuf, mFftBuf, mFftWork, PFFFT_FORWARD);

        // --- Phase vocoder: analysis → processing ---

        const float freqPerBin    = mSampleRate / static_cast<float>(mWindowSize);
        const float hopFactor     = static_cast<float>(mHopSize) / static_cast<float>(mWindowSize);
        const float twoPi         = 2.0f * static_cast<float>(M_PI);
        const float expectedPhaseInc = twoPi * hopFactor; // per bin = 2π * k * hop/N but we fold it

        // Unpack pffft ordered real output: [re0, re1, im1, re2, im2, ..., re(N/2)]
        // bin 0: mFftBuf[0] (real only), bin N/2: mFftBuf[1] (real only)
        // bins 1..(N/2-1): mFftBuf[2*k], mFftBuf[2*k+1]

        // Magnitude and instantaneous frequency for each bin
        for (int k = 0; k < mNumBins; ++k)
        {
            float re, im;
            if (k == 0)
            {
                re = mFftBuf[0]; im = 0.0f;
            }
            else if (k == mWindowSize / 2)
            {
                re = mFftBuf[1]; im = 0.0f;
            }
            else
            {
                re = mFftBuf[2 * k];
                im = mFftBuf[2 * k + 1];
            }

            mMag[k]   = std::sqrt(re * re + im * im);
            mPhase[k] = std::atan2(im, re);

            // Instantaneous frequency deviation
            float dPhase = mPhase[k] - mLastPhaseIn[k]
                           - static_cast<float>(k) * expectedPhaseInc;

            // Wrap to [-π, π]
            dPhase -= twoPi * std::round(dPhase / twoPi);

            // True frequency in bins
            mTrueFreq[k] = static_cast<float>(k) + dPhase / expectedPhaseInc;

            mLastPhaseIn[k] = mPhase[k];
        }

        // --- Phase locking: find peaks, lock neighbouring bins ---
        // A bin is a peak if its magnitude is >= its neighbours.
        std::memset(mPeakBin, 0, mNumBins * sizeof(int));
        for (int k = 1; k < mNumBins - 1; ++k)
        {
            if (mMag[k] >= mMag[k - 1] && mMag[k] >= mMag[k + 1])
                mPeakBin[k] = k; // mark as peak
        }
        // Assign each non-peak bin to its nearest peak
        // Forward pass
        int lastPeak = 0;
        for (int k = 0; k < mNumBins; ++k)
        {
            if (mPeakBin[k] == k) lastPeak = k;
            else                   mPeakBin[k] = lastPeak;
        }
        // Backward pass: if a bin is closer to the next peak, reassign
        int nextPeak = mNumBins - 1;
        for (int k = mNumBins - 1; k >= 0; --k)
        {
            if (mMag[k] >= (k > 0 ? mMag[k-1] : 0.0f) &&
                mMag[k] >= (k < mNumBins-1 ? mMag[k+1] : 0.0f))
                nextPeak = k;
            if (std::abs(k - nextPeak) < std::abs(k - mPeakBin[k]))
                mPeakBin[k] = nextPeak;
        }

        // --- Synthesis: pitch-shift by resampling bins ---
        std::memset(mSynthMag,   0, mNumBins * sizeof(float));
        std::memset(mSynthPhase, 0, mNumBins * sizeof(float));

        for (int k = 0; k < mNumBins; ++k)
        {
            const int   destBin = static_cast<int>(static_cast<float>(k) * mPitchRatio + 0.5f);
            if (destBin < 0 || destBin >= mNumBins) continue;

            // Accumulate magnitude (multiple source bins can map to same dest)
            mSynthMag[destBin] += mMag[k];

            // Phase: locked to the shifted peak bin's accumulated phase
            const int   srcPeak  = mPeakBin[k];
            const int   destPeak = static_cast<int>(static_cast<float>(srcPeak) * mPitchRatio + 0.5f);
            const float peakFreqShifted = mTrueFreq[srcPeak] * mPitchRatio;
            const float deltaPhasePeak  = peakFreqShifted * expectedPhaseInc;

            // Only accumulate phase for the peak bin itself; neighbours use the delta
            if (k == srcPeak && destPeak < mNumBins)
            {
                mSumPhaseOut[destPeak] += deltaPhasePeak;
                mSynthPhase[destBin]   = mSumPhaseOut[destPeak];
            }
            else if (destPeak < mNumBins)
            {
                // Phase-locked: offset from peak's accumulated phase
                const float phaseDiff = mPhase[k] - mPhase[srcPeak];
                mSynthPhase[destBin]  = mSumPhaseOut[destPeak] + phaseDiff;
            }
        }

        // Accumulate peak phases for next frame
        for (int k = 0; k < mNumBins; ++k)
        {
            if (mPeakBin[k] == k) // is a peak
            {
                const int destPeak = static_cast<int>(static_cast<float>(k) * mPitchRatio + 0.5f);
                if (destPeak < mNumBins && destPeak >= 0)
                    mSumPhaseOut[destPeak] = mSynthPhase[destPeak];
            }
        }

        // --- Pack synthesis bins back into FFT buffer ---
        std::memset(mFftBuf, 0, mWindowSize * sizeof(float));
        for (int k = 0; k < mNumBins; ++k)
        {
            const float mag = mSynthMag[k];
            const float ph  = mSynthPhase[k];
            const float re  = mag * std::cos(ph);
            const float im  = mag * std::sin(ph);

            if (k == 0)
            {
                mFftBuf[0] = re;
            }
            else if (k == mWindowSize / 2)
            {
                mFftBuf[1] = re;
            }
            else
            {
                mFftBuf[2 * k]     = re;
                mFftBuf[2 * k + 1] = im;
            }
        }

        // Inverse FFT
        pffft_transform_ordered(mPffftSetup, mFftBuf, mFftBuf, mFftWork, PFFFT_BACKWARD);

        // Normalise IFFT (pffft doesn't normalise)
        const float norm = mOlaScale / static_cast<float>(mWindowSize);
        for (int k = 0; k < mWindowSize; ++k)
            mFftBuf[k] *= norm;

        // Apply synthesis window and overlap-add into output accumulator
        for (int k = 0; k < mWindowSize; ++k)
            mOutputAccum[k] += mFftBuf[k] * mWindow[k];

        mOutputReady += mHopSize;
        // Shift accumulator to make room for next frame
        // (done sample-by-sample in process(), no need to shift here)
    }

    // ── Buffer management ─────────────────────────────────────────────────

    void allocBuffers()
    {
        // Use pffft_aligned_malloc for FFT buffers (required by pffft)
        mFftBuf       = static_cast<float*>(pffft_aligned_malloc(mWindowSize * sizeof(float)));
        mFftWork      = static_cast<float*>(pffft_aligned_malloc(mWindowSize * sizeof(float)));

        // Regular allocations for everything else
        mWindow       = new float[mWindowSize];
        mAnalysisFrame= new float[mWindowSize]();
        mInputBuf     = new float[mHopSize]();
        mOutputBuf    = new float[mWindowSize]();
        mOutputAccum  = new float[mWindowSize + mHopSize]();
        mMag          = new float[mNumBins]();
        mPhase        = new float[mNumBins]();
        mTrueFreq     = new float[mNumBins]();
        mLastPhaseIn  = new float[mNumBins]();
        mSumPhaseOut  = new float[mNumBins]();
        mSynthMag     = new float[mNumBins]();
        mSynthPhase   = new float[mNumBins]();
        mPeakBin      = new int[mNumBins]();

        mPffftSetup = pffft_new_setup(mWindowSize, PFFFT_REAL);
        mReady = (mPffftSetup != nullptr);
    }

    void freeBuffers()
    {
        if (mPffftSetup) { pffft_destroy_setup(mPffftSetup); mPffftSetup = nullptr; }
        if (mFftBuf)     { pffft_aligned_free(mFftBuf);      mFftBuf     = nullptr; }
        if (mFftWork)    { pffft_aligned_free(mFftWork);     mFftWork    = nullptr; }

        delete[] mWindow;       mWindow       = nullptr;
        delete[] mAnalysisFrame;mAnalysisFrame= nullptr;
        delete[] mInputBuf;     mInputBuf     = nullptr;
        delete[] mOutputBuf;    mOutputBuf    = nullptr;
        delete[] mOutputAccum;  mOutputAccum  = nullptr;
        delete[] mMag;          mMag          = nullptr;
        delete[] mPhase;        mPhase        = nullptr;
        delete[] mTrueFreq;     mTrueFreq     = nullptr;
        delete[] mLastPhaseIn;  mLastPhaseIn  = nullptr;
        delete[] mSumPhaseOut;  mSumPhaseOut  = nullptr;
        delete[] mSynthMag;     mSynthMag     = nullptr;
        delete[] mSynthPhase;   mSynthPhase   = nullptr;
        delete[] mPeakBin;      mPeakBin      = nullptr;

        mReady = false;
    }

    void buildWindow() noexcept
    {
        // Hann window, normalised for OLA reconstruction
        for (int k = 0; k < mWindowSize; ++k)
        {
            mWindow[k] = 0.5f * (1.0f - std::cos(2.0f * static_cast<float>(M_PI)
                                                   * k / static_cast<float>(mWindowSize)));
        }
    }

    // ── State ─────────────────────────────────────────────────────────────
    PFFFT_Setup* mPffftSetup  { nullptr };
    float*       mFftBuf      { nullptr };
    float*       mFftWork     { nullptr };
    float*       mWindow      { nullptr };
    float*       mAnalysisFrame { nullptr };
    float*       mInputBuf    { nullptr };
    float*       mOutputBuf   { nullptr };
    float*       mOutputAccum { nullptr };
    float*       mMag         { nullptr };
    float*       mPhase       { nullptr };
    float*       mTrueFreq    { nullptr };
    float*       mLastPhaseIn { nullptr };
    float*       mSumPhaseOut { nullptr };
    float*       mSynthMag    { nullptr };
    float*       mSynthPhase  { nullptr };
    int*         mPeakBin     { nullptr };

    float mSampleRate  { 44100.0f };
    float mPitchRatio  { 1.0f };
    float mOlaScale    { 1.0f };
    int   mWindowSize  { kDefaultWindowSize };
    int   mHopSize     { kDefaultWindowSize / kOverlapFactor };
    int   mNumBins     { kDefaultWindowSize / 2 + 1 };
    int   mInputFill   { 0 };
    int   mOutputReady { 0 };
    bool  mReady       { false };
};

} // namespace Octofilter

