#pragma once

#include "IPitchShifter.hpp"
#include "pffft.h"

#include <cmath>
#include <cstring>

namespace Octofilter
{

/**
 * PhaseVocoderShifter — real-time phase vocoder pitch shifter.
 *
 * Algorithm:
 *   Analysis:   Accumulate input into a sliding frame. Every hopSize samples,
 *               window + FFT the latest windowSize samples.
 *   Processing: Compute instantaneous frequency per bin via phase difference.
 *               Phase lock each bin to its nearest magnitude peak.
 *               Remap bins by pitch ratio.
 *   Synthesis:  IFFT, window, overlap-add into output ring buffer.
 *               Read output with hopSize stride.
 *
 * Latency = windowSize samples.
 * All buffers allocated in prepare() — zero RT allocations.
 */
class PhaseVocoderShifter final : public IPitchShifter
{
public:
    static constexpr int kDefaultWindowSize = 512;
    static constexpr int kOverlapFactor     = 4;

    ~PhaseVocoderShifter() override { freeBuffers(); }

    // ── IPitchShifter ─────────────────────────────────────────────────────

    void prepare(double sampleRate, int /*maxBlockSize*/) override
    {
        freeBuffers();

        mSampleRate = static_cast<float>(sampleRate);
        mWindowSize = kDefaultWindowSize;
        mHopSize    = mWindowSize / kOverlapFactor;
        mNumBins    = mWindowSize / 2 + 1;

        allocBuffers();
        buildWindow();
        reset();
    }

    void setShift(float semitones) override
    {
        if (semitones >  24.0f) semitones =  24.0f;
        if (semitones < -24.0f) semitones = -24.0f;
        mPitchRatio = std::pow(2.0f, semitones / 12.0f);
    }

    void reset() override
    {
        if (!mReady) return;

        std::memset(mAnalysisFrame, 0, mWindowSize * sizeof(float));
        std::memset(mFftBuf,        0, mWindowSize * sizeof(float));
        std::memset(mFftWork,       0, mWindowSize * sizeof(float));
        std::memset(mLastPhaseIn,   0, mNumBins    * sizeof(float));
        std::memset(mSumPhaseOut,   0, mNumBins    * sizeof(float));
        std::memset(mOutputRing,    0, mOutputRingSize * sizeof(float));

        mInHopAccum  = 0;
        mOutReadPos  = 0;
        mOutWritePos = 0;
        mOutputFill  = 0;
    }

    int getLatencySamples() const override { return mWindowSize; }

    void process(const float* in, float* out, int numSamples) override
    {
        for (int i = 0; i < numSamples; ++i)
        {
            // Push sample into analysis frame (shift left, append)
            // We keep a running windowSize-sample frame; every hopSize
            // samples we process a new frame.
            pushSample(in[i]);
            ++mInHopAccum;

            if (mInHopAccum >= mHopSize)
            {
                mInHopAccum = 0;
                processFrame();
            }

            // Read from output ring (will be silence for first windowSize samples)
            out[i] = readOutput();
        }
    }

private:
    // ── Per-sample helpers ────────────────────────────────────────────────

    void pushSample(float x) noexcept
    {
        // Slide analysis frame left by 1 and append new sample at the end
        // For efficiency, we use a ring buffer indexed by mInWritePos
        mAnalysisFrame[mInWritePos] = x;
        mInWritePos = (mInWritePos + 1) % mWindowSize;
    }

    float readOutput() noexcept
    {
        if (mOutputFill <= 0) return 0.0f;
        const float s = mOutputRing[mOutReadPos];
        mOutputRing[mOutReadPos] = 0.0f; // clear after read
        mOutReadPos = (mOutReadPos + 1) % mOutputRingSize;
        --mOutputFill;
        return s;
    }

    // ── Frame processing ──────────────────────────────────────────────────

    void processFrame() noexcept
    {
        // --- Copy windowSize samples from ring into FFT buf, apply window ---
        for (int k = 0; k < mWindowSize; ++k)
        {
            const int idx = (mInWritePos + k) % mWindowSize;
            mFftBuf[k] = mAnalysisFrame[idx] * mWindow[k];
        }

        // --- Forward FFT ---
        pffft_transform_ordered(mPffftSetup, mFftBuf, mFftBuf, mFftWork, PFFFT_FORWARD);

        // --- Analysis: magnitude, phase, instantaneous frequency ---
        const float twoPi         = 2.0f * static_cast<float>(M_PI);
        const float expPhaseInc   = twoPi * static_cast<float>(mHopSize)
                                    / static_cast<float>(mWindowSize);

        for (int k = 0; k < mNumBins; ++k)
        {
            float re, im;
            getBin(k, re, im);

            mMag[k]   = std::sqrt(re * re + im * im);
            mPhase[k] = std::atan2(im, re);

            float dPhi = mPhase[k] - mLastPhaseIn[k]
                         - static_cast<float>(k) * expPhaseInc;
            // Wrap to [-π, π]
            dPhi -= twoPi * std::round(dPhi / twoPi);

            mTrueFreq[k]    = static_cast<float>(k) + dPhi / expPhaseInc;
            mLastPhaseIn[k] = mPhase[k];
        }

        // --- Phase locking ---
        // Assign each bin to its nearest magnitude peak
        for (int k = 0; k < mNumBins; ++k) mPeakBin[k] = k;

        // Forward pass
        int lastPeak = 0;
        for (int k = 0; k < mNumBins; ++k)
        {
            bool isPeak = true;
            if (k > 0           && mMag[k] < mMag[k-1]) isPeak = false;
            if (k < mNumBins-1  && mMag[k] < mMag[k+1]) isPeak = false;
            if (isPeak) lastPeak = k;
            else        mPeakBin[k] = lastPeak;
        }
        // Backward pass: reassign if nearer to a later peak
        int nextPeak = mNumBins - 1;
        for (int k = mNumBins - 1; k >= 0; --k)
        {
            bool isPeak = true;
            if (k > 0           && mMag[k] < mMag[k-1]) isPeak = false;
            if (k < mNumBins-1  && mMag[k] < mMag[k+1]) isPeak = false;
            if (isPeak) nextPeak = k;
            if (std::abs(k - nextPeak) < std::abs(k - mPeakBin[k]))
                mPeakBin[k] = nextPeak;
        }

        // --- Synthesis: pitch-shift by remapping bins ---
        std::memset(mSynthMag,   0, mNumBins * sizeof(float));
        std::memset(mSynthPhase, 0, mNumBins * sizeof(float));

        for (int k = 0; k < mNumBins; ++k)
        {
            const int destBin = static_cast<int>(
                static_cast<float>(k) * mPitchRatio + 0.5f);
            if (destBin < 0 || destBin >= mNumBins) continue;

            if (mMag[k] > mSynthMag[destBin])
                mSynthMag[destBin] = mMag[k];

            const int   srcPeak  = mPeakBin[k];
            const int   destPeak = static_cast<int>(
                static_cast<float>(srcPeak) * mPitchRatio + 0.5f);

            if (destPeak >= 0 && destPeak < mNumBins)
            {
                // Accumulate peak phase
                mSumPhaseOut[destPeak] += mTrueFreq[srcPeak] * mPitchRatio * expPhaseInc;
                const float phaseDiff   = mPhase[k] - mPhase[srcPeak];
                mSynthPhase[destBin]    = mSumPhaseOut[destPeak] + phaseDiff;
            }
        }

        // --- Pack synthesis bins and IFFT ---
        std::memset(mFftBuf, 0, mWindowSize * sizeof(float));
        for (int k = 0; k < mNumBins; ++k)
            setBin(k, mSynthMag[k] * std::cos(mSynthPhase[k]),
                      mSynthMag[k] * std::sin(mSynthPhase[k]));

        pffft_transform_ordered(mPffftSetup, mFftBuf, mFftBuf, mFftWork, PFFFT_BACKWARD);

        // Normalise and apply synthesis window
        const float norm = 2.0f / (static_cast<float>(kOverlapFactor)
                                   * static_cast<float>(mWindowSize));
        for (int k = 0; k < mWindowSize; ++k)
            mFftBuf[k] *= mWindow[k] * norm;

        // Overlap-add into output ring
        for (int k = 0; k < mWindowSize; ++k)
        {
            const int pos = (mOutWritePos + k) % mOutputRingSize;
            mOutputRing[pos] += mFftBuf[k];
        }

        mOutWritePos  = (mOutWritePos + mHopSize) % mOutputRingSize;
        mOutputFill  += mHopSize;
        if (mOutputFill > mOutputRingSize) mOutputFill = mOutputRingSize;
    }

    // ── pffft bin helpers (ordered real format) ───────────────────────────
    // pffft ordered real: [re0, re(N/2), re1, im1, re2, im2, ...]

    void getBin(int k, float& re, float& im) const noexcept
    {
        if (k == 0)              { re = mFftBuf[0]; im = 0.0f; }
        else if (k == mWindowSize/2) { re = mFftBuf[1]; im = 0.0f; }
        else                     { re = mFftBuf[2*k]; im = mFftBuf[2*k+1]; }
    }

    void setBin(int k, float re, float im) noexcept
    {
        if (k == 0)              { mFftBuf[0] = re; }
        else if (k == mWindowSize/2) { mFftBuf[1] = re; }
        else                     { mFftBuf[2*k] = re; mFftBuf[2*k+1] = im; }
    }

    // ── Buffer management ─────────────────────────────────────────────────

    void allocBuffers()
    {
        mOutputRingSize = mWindowSize * 4; // plenty of headroom for OLA

        mFftBuf       = static_cast<float*>(pffft_aligned_malloc(mWindowSize * sizeof(float)));
        mFftWork      = static_cast<float*>(pffft_aligned_malloc(mWindowSize * sizeof(float)));

        mWindow        = new float[mWindowSize]();
        mAnalysisFrame = new float[mWindowSize]();
        mOutputRing    = new float[mOutputRingSize]();
        mMag           = new float[mNumBins]();
        mPhase         = new float[mNumBins]();
        mTrueFreq      = new float[mNumBins]();
        mLastPhaseIn   = new float[mNumBins]();
        mSumPhaseOut   = new float[mNumBins]();
        mSynthMag      = new float[mNumBins]();
        mSynthPhase    = new float[mNumBins]();
        mPeakBin       = new int[mNumBins]();

        mPffftSetup = pffft_new_setup(mWindowSize, PFFFT_REAL);
        mReady      = (mPffftSetup != nullptr);
    }

    void freeBuffers()
    {
        if (mPffftSetup) { pffft_destroy_setup(mPffftSetup); mPffftSetup = nullptr; }
        if (mFftBuf)     { pffft_aligned_free(mFftBuf);      mFftBuf     = nullptr; }
        if (mFftWork)    { pffft_aligned_free(mFftWork);     mFftWork    = nullptr; }

        delete[] mWindow;        mWindow        = nullptr;
        delete[] mAnalysisFrame; mAnalysisFrame = nullptr;
        delete[] mOutputRing;    mOutputRing    = nullptr;
        delete[] mMag;           mMag           = nullptr;
        delete[] mPhase;         mPhase         = nullptr;
        delete[] mTrueFreq;      mTrueFreq      = nullptr;
        delete[] mLastPhaseIn;   mLastPhaseIn   = nullptr;
        delete[] mSumPhaseOut;   mSumPhaseOut   = nullptr;
        delete[] mSynthMag;      mSynthMag      = nullptr;
        delete[] mSynthPhase;    mSynthPhase    = nullptr;
        delete[] mPeakBin;       mPeakBin       = nullptr;

        mReady = false;
    }

    void buildWindow() noexcept
    {
        for (int k = 0; k < mWindowSize; ++k)
            mWindow[k] = 0.5f * (1.0f - std::cos(2.0f * static_cast<float>(M_PI)
                                                   * k / static_cast<float>(mWindowSize)));
    }

    // ── Members ───────────────────────────────────────────────────────────
    PFFFT_Setup* mPffftSetup    { nullptr };
    float*       mFftBuf        { nullptr };
    float*       mFftWork       { nullptr };
    float*       mWindow        { nullptr };
    float*       mAnalysisFrame { nullptr };
    float*       mOutputRing    { nullptr };
    float*       mMag           { nullptr };
    float*       mPhase         { nullptr };
    float*       mTrueFreq      { nullptr };
    float*       mLastPhaseIn   { nullptr };
    float*       mSumPhaseOut   { nullptr };
    float*       mSynthMag      { nullptr };
    float*       mSynthPhase    { nullptr };
    int*         mPeakBin       { nullptr };

    float mSampleRate   { 44100.0f };
    float mPitchRatio   { 1.0f };
    int   mWindowSize   { kDefaultWindowSize };
    int   mHopSize      { kDefaultWindowSize / kOverlapFactor };
    int   mNumBins      { kDefaultWindowSize / 2 + 1 };
    int   mOutputRingSize { kDefaultWindowSize * 4 };
    int   mInWritePos   { 0 };
    int   mInHopAccum   { 0 };
    int   mOutReadPos   { 0 };
    int   mOutWritePos  { 0 };
    int   mOutputFill   { 0 };
    bool  mReady        { false };
};

} // namespace Octofilter

