// ── Parameter count ───────────────────────────────────────────────────────────
// 11 globals + 7 per-point × 8 points = 67
static constexpr int kNumGlobalParams   = 11;
static constexpr int kNumPerPointParams = 7;
static constexpr int kNumPoints         = 8;
static constexpr int kTotalParams       = kNumGlobalParams + kNumPerPointParams * kNumPoints;

// ── Parameter smoothing ───────────────────────────────────────────────────────
struct ParamSmoother
{
    float current { 0.0f };
    float coeff   { 0.99f }; // ~10 ms at 44.1 kHz

    void setTargetRate(float sampleRate) noexcept
    {
        coeff = std::exp(-1.0f / (0.010f * sampleRate));
    }

    void set(float v) noexcept { current = v; }
    void setTarget(float target) noexcept { current += (1.0f - coeff) * (target - current); }
    float get() const noexcept { return current; }
};

