{
    const bool harmonic = (mHarmonicMode > 0.5f);
    const float fundamental = Octofilter::HarmonicMapper::textureToFundamental(mTexture);

    for (int i = 0; i < mActivePoints; ++i)
    {
        Octofilter::PointState& pt = mPoints[i];
        const float q = (mPointQ[i] > 0.0f) ? mPointQ[i] : mResonance;

        float targetCutoff;
        if (harmonic)
        {
            // Harmonic mode: target is harmonic of Texture frequency
            // Spread controls how far up the harmonic series we reach
            targetCutoff = Octofilter::HarmonicMapper::targetCutoff(
                fundamental, i, mActivePoints, mSpread);
        }
        else
        {
            // Random mode: Texture + per-point offset scaled by Spread
            // At spread=0: all points converge to Texture centre frequency
            // At spread=1: full individual offsets applied
            targetCutoff = Octofilter::TextureMapper::computeCutoff(
                mTexture, pt.cutoffOffsetSemitones, mSpread);
        }

        // Set glide target
        mGlide[i].setTarget(targetCutoff);

        // Apply current glided cutoff to filter
        pt.applyFilterParams(mGlide[i].current, q);
    }
}

