    if (mShifter)
    {
        mShifter->process(&filteredOutput, &shifted, 1);
    }

    // 2. DC block
    const float dcBlocked = mDCBlocker.process(shifted);

    // 3. Limit
    mFeedbackSample = mLimiter.process(dcBlocked);
}

