void OctofilterPlugin::updateFilterParams() noexcept
{
    const bool harmonic = (mHarmonicMode > 0.5f);

    // Texture controls "how open" everything is:
    //   0 = collapsed (all filters at min cutoff, mono, no spread)
    //   1 = fully configured state (per-point offsets, full pan, full spread)
    const float openness = mTexture;

    // Base frequency: interpolate between 20 Hz (collapsed) and the configured centre
    // In harmonic mode the "configured centre" is derived from spread+harmonics
    // In random mode it's the Texture position on the log scale
    const float collapsedFreq = 20.0f;
    const float fullFreq      = Octofilter::TextureMapper::textureToCentreFreq(1.0f); // 20kHz at max

    for (int i = 0; i < mActivePoints; ++i)
    {
        Octofilter::PointState& pt = mPoints[i];
        const float q = (mPointQ[i] > 0.0f) ? mPointQ[i] : mResonance;

        float targetCutoff;
        if (harmonic)
        {
            // Harmonic mode: target is harmonic of a fundamental that scales with openness
            const float fundamental = collapsedFreq + openness * (
                Octofilter::HarmonicMapper::textureToFundamental(openness) - collapsedFreq);
            targetCutoff = Octofilter::HarmonicMapper::targetCutoff(
                fundamental, i, mActivePoints, mSpread * openness);
        }
        else
        {
            // Random mode: interpolate between collapsed (all at 20Hz) and 
            // full configured position (centre freq + per-point offset scaled by spread)
            const float configuredCutoff = Octofilter::TextureMapper::computeCutoff(
                1.0f, pt.cutoffOffsetSemitones, mSpread);
            targetCutoff = collapsedFreq + openness * (configuredCutoff - collapsedFreq);
        }

        mGlide[i].setTarget(targetCutoff);
        pt.applyFilterParams(mGlide[i].current, q);

        // Pan also collapses with texture: at 0 = centre, at 1 = configured position
        mPoints[i].pan = mPointPan[i] * openness;
    }
}

