#include "DistrhoUI.hpp"
#include "InterFont.hpp"

START_NAMESPACE_DISTRHO

// ── Blodyn Tatws colour palette ───────────────────────────────────────────────
namespace Palette
{
    static constexpr Color bg         {0.16f, 0.16f, 0.16f}; // dark background
    static constexpr Color fieldBg    {0.60f, 0.65f, 0.46f, 0.3f}; // sage green, translucent
    static constexpr Color text       {0.99f, 0.98f, 0.85f}; // warm white #fdfada
    static constexpr Color accent     {0.655f, 0.498f, 0.682f}; // purple #a77fae
    static constexpr Color accentLight{0.929f, 0.792f, 0.914f}; // pink #edcae9
    static constexpr Color highlight  {0.992f, 0.753f, 0.027f}; // gold #fdc007
    static constexpr Color outline    {0.631f, 0.439f, 0.275f}; // brown #a17046
    static constexpr Color sage       {0.60f, 0.65f, 0.46f};  // sage green #99a575

    // Filter type colours
    static constexpr Color filterLP   {0.655f, 0.498f, 0.682f}; // purple
    static constexpr Color filterHP   {0.992f, 0.753f, 0.027f}; // gold
    static constexpr Color filterBP   {0.60f, 0.65f, 0.46f};    // sage
    static constexpr Color filterNotch{0.929f, 0.792f, 0.914f}; // pink

    static Color filterColor(int type)
    {
        switch (type)
        {
        case 0: return filterLP;
        case 1: return filterHP;
        case 2: return filterBP;
        case 3: return filterNotch;
        default: return text;
        }
    }
}

// ── Parameter indices (must match plugin) ─────────────────────────────────────
enum GlobalParams : uint32_t
{
    kGlobalPointCount   = 0,
    kGlobalTexture      = 1,
    kGlobalTextureSpread= 2,
    kGlobalSpread       = 3,
    kGlobalResonance    = 4,
    kGlobalFeedback     = 5,
    kGlobalPitchShift   = 6,
    kGlobalInputGain    = 7,
    kGlobalOutputGain   = 8,
    kGlobalWetDry       = 9,
    kGlobalRandomise    = 10,
    kGlobalHarmonicMode = 11,
    kGlobalGlideTime    = 12,
};

static constexpr int kNumGlobalParams   = 13;
static constexpr int kNumPerPointParams = 7;

enum PerPointOffset : uint32_t
{
    kPPFilterType   = 0,
    kPPCutoffOffset = 1,
    kPPQ            = 2,
    kPPPan          = 3,
    kPPLevel        = 4,
    kPPFeedback     = 5,
    kPPPitchShift   = 6,
};

static uint32_t ppIdx(int point, PerPointOffset off)
{
    return kNumGlobalParams + point * kNumPerPointParams + static_cast<int>(off);
}

// ── UI dimensions ─────────────────────────────────────────────────────────────
static constexpr uint kDefaultWidth  = 700;
static constexpr uint kDefaultHeight = 450;

// ── Knob helper struct ────────────────────────────────────────────────────────
struct Knob
{
    float x, y, radius;
    float min, max, value;
    uint32_t paramIndex;
    const char* label;
    bool dragging = false;
};

// ═══════════════════════════════════════════════════════════════════════════════
class OctofilterUI : public UI
{
public:
    OctofilterUI()
        : UI(kDefaultWidth, kDefaultHeight)
    {
        // Load embedded Inter font
        fFontId = createFontFromMemory("inter", kInterFontData, kInterFontDataSize, false);

        setGeometryConstraints(600, 400, true);

        // Init knobs
        setupKnobs();

        // Init point params to defaults
        for (int i = 0; i < 8; ++i)
        {
            fPointFilterType[i] = 0.0f;
            fPointPan[i]        = 0.0f;
            fPointLevel[i]      = 1.0f;
            fPointFeedback[i]   = 0.0f;
            fPointPitchShift[i] = 0.0f;
            fPointQ[i]          = 0.0f;
        }
    }

protected:
    // ── DPF callbacks ─────────────────────────────────────────────────────
    void parameterChanged(uint32_t index, float value) override
    {
        // Global params
        if (index == kGlobalPointCount)    { fPointCount = static_cast<int>(value + 0.5f); repaint(); return; }
        if (index == kGlobalTexture)       { fTexture = value; repaint(); return; }
        if (index == kGlobalResonance)     { fResonance = value; repaint(); return; }
        if (index == kGlobalFeedback)      { fFeedback = value; repaint(); return; }
        if (index == kGlobalPitchShift)    { fPitchShift = value; repaint(); return; }
        if (index == kGlobalInputGain)     { fInputGain = value; repaint(); return; }
        if (index == kGlobalOutputGain)    { fOutputGain = value; repaint(); return; }
        if (index == kGlobalWetDry)        { fWetDry = value; repaint(); return; }
        if (index == kGlobalHarmonicMode)  { fHarmonicMode = value; repaint(); return; }
        if (index == kGlobalGlideTime)     { fGlideTime = value; repaint(); return; }

        // Per-point params
        if (index >= kNumGlobalParams)
        {
            const int rel   = static_cast<int>(index) - kNumGlobalParams;
            const int point = rel / kNumPerPointParams;
            const int off   = rel % kNumPerPointParams;
            if (point >= 8) return;

            switch (off)
            {
            case kPPFilterType:  fPointFilterType[point] = value; break;
            case kPPPan:         fPointPan[point] = value; break;
            case kPPLevel:       fPointLevel[point] = value; break;
            case kPPFeedback:    fPointFeedback[point] = value; break;
            case kPPPitchShift:  fPointPitchShift[point] = value; break;
            case kPPQ:           fPointQ[point] = value; break;
            default: break;
            }
            repaint();
        }
    }

    void stateChanged(const char*, const char*) override {}

    // ── Drawing ───────────────────────────────────────────────────────────
    void onNanoDisplay() override
    {
        const float w = static_cast<float>(getWidth());
        const float h = static_cast<float>(getHeight());

        // Background
        beginPath();
        rect(0, 0, w, h);
        fillColor(Palette::bg);
        fill();

        // Layout regions
        const float fieldW = w * 0.6f;
        const float fieldH = h * 0.7f;
        const float fieldX = 10.0f;
        const float fieldY = 40.0f;
        const float stripX = fieldW + 20.0f;
        const float stripW = w - stripX - 10.0f;
        const float panelY = fieldY + fieldH + 10.0f;
        const float panelH = h - panelY - 10.0f;

        // Title
        fontSize(16.0f);
        fontFaceId(fFontId);
        fillColor(Palette::text);
        textAlign(ALIGN_LEFT | ALIGN_TOP);
        text(12.0f, 12.0f, "OCTOFILTER", nullptr);

        // Point count display
        fontSize(12.0f);
        char pcBuf[32];
        std::snprintf(pcBuf, sizeof(pcBuf), "Points: %d", fPointCount);
        textAlign(ALIGN_RIGHT | ALIGN_TOP);
        text(w - 12.0f, 12.0f, pcBuf, nullptr);

        drawStereoField(fieldX, fieldY, fieldW, fieldH);
        drawGlobalStrip(stripX, fieldY, stripW, fieldH);
        drawPerPointPanel(fieldX, panelY, w - 20.0f, panelH);
    }

    // ── Mouse interaction ─────────────────────────────────────────────────
    bool onMouse(const MouseEvent& ev) override
    {
        if (ev.button != 1) return false;

        if (ev.press)
        {
            // Check knob hits
            for (auto& k : fKnobs)
            {
                const float dx = ev.pos.getX() - k.x;
                const float dy = ev.pos.getY() - k.y;
                if (dx * dx + dy * dy < k.radius * k.radius * 1.5f)
                {
                    k.dragging = true;
                    fDragStartY = ev.pos.getY();
                    fDragStartValue = k.value;
                    return true;
                }
            }

            // Check point node hits in stereo field
            const float fieldW = getWidth() * 0.6f;
            const float fieldH = getHeight() * 0.7f;
            const float fieldX = 10.0f;
            const float fieldY = 40.0f;

            for (int i = 0; i < fPointCount; ++i)
            {
                const float px = fieldX + (fPointPan[i] + 1.0f) * 0.5f * fieldW;
                const float py = fieldY + fieldH - (fTexture * fieldH); // simplified Y
                const float dx = ev.pos.getX() - px;
                const float dy = ev.pos.getY() - py;
                if (dx * dx + dy * dy < 200.0f)
                {
                    fSelectedPoint = i;
                    fDraggingPoint = true;
                    repaint();
                    return true;
                }
            }
        }
        else
        {
            // Release
            for (auto& k : fKnobs)
                k.dragging = false;
            fDraggingPoint = false;
        }
        return false;
    }

    bool onMotion(const MotionEvent& ev) override
    {
        // Knob dragging
        for (auto& k : fKnobs)
        {
            if (k.dragging)
            {
                const float dy = fDragStartY - ev.pos.getY();
                const float range = k.max - k.min;
                const float sensitivity = range / 200.0f;
                float newVal = fDragStartValue + dy * sensitivity;
                if (newVal < k.min) newVal = k.min;
                if (newVal > k.max) newVal = k.max;
                k.value = newVal;
                setParameterValue(k.paramIndex, newVal);
                repaint();
                return true;
            }
        }

        // Point dragging (sets pan)
        if (fDraggingPoint && fSelectedPoint >= 0)
        {
            const float fieldW = getWidth() * 0.6f;
            const float fieldX = 10.0f;
            float pan = (ev.pos.getX() - fieldX) / fieldW * 2.0f - 1.0f;
            if (pan < -1.0f) pan = -1.0f;
            if (pan > 1.0f) pan = 1.0f;
            fPointPan[fSelectedPoint] = pan;
            setParameterValue(ppIdx(fSelectedPoint, kPPPan), pan);
            repaint();
            return true;
        }
        return false;
    }

private:
    // ── Drawing helpers ───────────────────────────────────────────────────

    void drawStereoField(float x, float y, float w, float h)
    {
        // Background
        beginPath();
        roundedRect(x, y, w, h, 6.0f);
        fillColor(Palette::fieldBg);
        fill();
        strokeColor(Palette::outline);
        strokeWidth(1.0f);
        stroke();

        // L/R labels
        fontSize(10.0f);
        fontFaceId(fFontId);
        fillColor(Palette::text);
        textAlign(ALIGN_LEFT | ALIGN_BOTTOM);
        text(x + 4.0f, y + h - 4.0f, "L", nullptr);
        textAlign(ALIGN_RIGHT | ALIGN_BOTTOM);
        text(x + w - 4.0f, y + h - 4.0f, "R", nullptr);

        // Centre line
        beginPath();
        moveTo(x + w * 0.5f, y);
        lineTo(x + w * 0.5f, y + h);
        strokeColor(Color(1.0f, 1.0f, 1.0f, 0.1f));
        strokeWidth(0.5f);
        stroke();

        // Draw point nodes
        for (int i = 0; i < fPointCount; ++i)
        {
            const float pan = fPointPan[i];
            const float px  = x + (pan + 1.0f) * 0.5f * w;
            // Y = cutoff representation (texture * point's relative position)
            const float normalizedY = 0.2f + 0.6f * fTexture; // simple for now
            const float py  = y + h - normalizedY * h;

            // Size based on feedback amount
            const float baseSize = 8.0f;
            const float fbSize   = baseSize + fPointFeedback[i] * 12.0f;

            // Colour by filter type
            const int ftype = static_cast<int>(fPointFilterType[i] + 0.5f) % 4;
            Color nodeColor = Palette::filterColor(ftype);

            // Selected highlight
            if (i == fSelectedPoint)
            {
                beginPath();
                circle(px, py, fbSize + 4.0f);
                strokeColor(Palette::highlight);
                strokeWidth(2.0f);
                stroke();
            }

            // Node fill
            beginPath();
            circle(px, py, fbSize);
            fillColor(nodeColor);
            fill();

            // Pitch shift ring (outline thickness)
            const float pitchRing = std::fabs(fPointPitchShift[i]) * 0.1f;
            if (pitchRing > 0.5f)
            {
                beginPath();
                circle(px, py, fbSize + 2.0f);
                strokeColor(Palette::text);
                strokeWidth(pitchRing);
                stroke();
            }

            // Point number label
            fontSize(9.0f);
            fillColor(Palette::bg);
            textAlign(ALIGN_CENTER | ALIGN_MIDDLE);
            char num[4];
            std::snprintf(num, sizeof(num), "%d", i + 1);
            text(px, py, num, nullptr);
        }
    }

    void drawGlobalStrip(float x, float y, float w, float h)
    {
        // Title
        fontSize(11.0f);
        fontFaceId(fFontId);
        fillColor(Palette::text);
        textAlign(ALIGN_LEFT | ALIGN_TOP);
        text(x, y - 2.0f, "CONTROLS", nullptr);

        // Draw each knob
        const float knobSpacing = h / (static_cast<float>(fNumGlobalKnobs) + 0.5f);
        for (int i = 0; i < fNumGlobalKnobs; ++i)
        {
            Knob& k = fKnobs[i];
            k.x = x + w * 0.5f;
            k.y = y + 20.0f + i * knobSpacing;
            k.radius = 14.0f;
            drawKnob(k);
        }
    }

    void drawPerPointPanel(float x, float y, float w, float h)
    {
        // Background
        beginPath();
        roundedRect(x, y, w, h, 4.0f);
        fillColor(Color(0.12f, 0.12f, 0.12f));
        fill();

        if (fSelectedPoint < 0 || fSelectedPoint >= fPointCount)
        {
            fontSize(11.0f);
            fontFaceId(fFontId);
            fillColor(Palette::accentLight);
            textAlign(ALIGN_CENTER | ALIGN_MIDDLE);
            text(x + w * 0.5f, y + h * 0.5f, "Click a point to edit", nullptr);
            return;
        }

        // Header
        fontSize(11.0f);
        fontFaceId(fFontId);
        fillColor(Palette::highlight);
        textAlign(ALIGN_LEFT | ALIGN_TOP);
        char hdr[32];
        std::snprintf(hdr, sizeof(hdr), "POINT %d", fSelectedPoint + 1);
        text(x + 8.0f, y + 4.0f, hdr, nullptr);

        // Per-point knobs (laid out horizontally)
        const float kx = x + 40.0f;
        const float ky = y + h * 0.5f;
        const float spacing = w / 7.0f;

        // We draw simplified per-point knobs inline
        const char* labels[] = {"Type", "Q", "Pan", "Level", "FB", "Pitch"};
        float* values[] = {
            &fPointFilterType[fSelectedPoint],
            &fPointQ[fSelectedPoint],
            &fPointPan[fSelectedPoint],
            &fPointLevel[fSelectedPoint],
            &fPointFeedback[fSelectedPoint],
            &fPointPitchShift[fSelectedPoint]
        };
        float mins[] = {0, 0, -1, 0, 0, -24};
        float maxs[] = {3, 20, 1, 2, 1, 24};

        for (int i = 0; i < 6; ++i)
        {
            const float cx = kx + i * spacing;
            drawMiniKnob(cx, ky, 10.0f, *values[i], mins[i], maxs[i], labels[i]);
        }
    }

    void drawKnob(const Knob& k)
    {
        // Arc background
        const float startAngle = 0.75f * 3.14159f;
        const float endAngle   = 2.25f * 3.14159f;
        const float range      = endAngle - startAngle;
        const float normalized = (k.value - k.min) / (k.max - k.min);
        const float valueAngle = startAngle + normalized * range;

        // Track
        beginPath();
        arc(k.x, k.y, k.radius, startAngle, endAngle, NanoVG::CCW);
        strokeColor(Palette::outline);
        strokeWidth(3.0f);
        stroke();

        // Value arc
        beginPath();
        arc(k.x, k.y, k.radius, startAngle, valueAngle, NanoVG::CCW);
        strokeColor(Palette::accent);
        strokeWidth(3.0f);
        stroke();

        // Centre dot
        beginPath();
        circle(k.x, k.y, 3.0f);
        fillColor(Palette::text);
        fill();

        // Label
        fontSize(9.0f);
        fontFaceId(fFontId);
        fillColor(Palette::text);
        textAlign(ALIGN_CENTER | ALIGN_TOP);
        text(k.x, k.y + k.radius + 4.0f, k.label, nullptr);
    }

    void drawMiniKnob(float cx, float cy, float r, float value,
                      float min, float max, const char* label)
    {
        const float startAngle = 0.75f * 3.14159f;
        const float endAngle   = 2.25f * 3.14159f;
        const float range      = endAngle - startAngle;
        const float normalized = (max > min) ? (value - min) / (max - min) : 0.0f;
        const float valueAngle = startAngle + normalized * range;

        beginPath();
        arc(cx, cy, r, startAngle, endAngle, NanoVG::CCW);
        strokeColor(Palette::outline);
        strokeWidth(2.0f);
        stroke();

        beginPath();
        arc(cx, cy, r, startAngle, valueAngle, NanoVG::CCW);
        strokeColor(Palette::accent);
        strokeWidth(2.0f);
        stroke();

        fontSize(8.0f);
        fontFaceId(fFontId);
        fillColor(Palette::text);
        textAlign(ALIGN_CENTER | ALIGN_TOP);
        text(cx, cy + r + 3.0f, label, nullptr);
    }

    void setupKnobs()
    {
        fNumGlobalKnobs = 0;
        auto addKnob = [&](uint32_t idx, float min, float max, float def, const char* lbl) {
            Knob k;
            k.paramIndex = idx;
            k.min = min; k.max = max; k.value = def;
            k.label = lbl;
            k.x = 0; k.y = 0; k.radius = 14.0f;
            fKnobs[fNumGlobalKnobs++] = k;
        };

        addKnob(kGlobalTexture,    0.0f, 1.0f,  0.5f,   "Texture");
        addKnob(kGlobalResonance,  0.1f, 20.0f, 0.707f, "Reso");
        addKnob(kGlobalFeedback,   0.0f, 1.0f,  0.3f,   "Feedback");
        addKnob(kGlobalPitchShift, -24.f, 24.f, 0.0f,   "Pitch");
        addKnob(kGlobalWetDry,     0.0f, 1.0f,  1.0f,   "Wet/Dry");
        addKnob(kGlobalInputGain,  -24.f, 24.f, 0.0f,   "In Gain");
        addKnob(kGlobalOutputGain, -24.f, 24.f, 0.0f,   "Out Gain");
        addKnob(kGlobalGlideTime,  10.f, 2000.f, 200.f, "Glide");
    }

    // ── State ─────────────────────────────────────────────────────────────
    int   fFontId { -1 };
    int   fPointCount { 2 };
    int   fSelectedPoint { -1 };
    bool  fDraggingPoint { false };
    float fDragStartY { 0.0f };
    float fDragStartValue { 0.0f };

    // Global params (mirrored)
    float fTexture     { 0.5f };
    float fResonance   { 0.707f };
    float fFeedback    { 0.3f };
    float fPitchShift  { 0.0f };
    float fWetDry      { 1.0f };
    float fInputGain   { 0.0f };
    float fOutputGain  { 0.0f };
    float fHarmonicMode{ 0.0f };
    float fGlideTime   { 200.0f };

    // Per-point params (mirrored)
    float fPointFilterType[8] {};
    float fPointPan[8] {};
    float fPointLevel[8] {};
    float fPointFeedback[8] {};
    float fPointPitchShift[8] {};
    float fPointQ[8] {};

    // Knobs
    static constexpr int kMaxKnobs = 16;
    Knob  fKnobs[kMaxKnobs] {};
    int   fNumGlobalKnobs { 0 };

    DISTRHO_DECLARE_NON_COPYABLE_WITH_LEAK_DETECTOR(OctofilterUI)
};

// ── DPF UI entry point ────────────────────────────────────────────────────────
UI* createUI()
{
    return new OctofilterUI();
}

END_NAMESPACE_DISTRHO

