// ── Global controls (bottom strip) ────────────────────────────────────
void drawGlobalStrip(float x, float y, float w, float h)
{
    beginPath();
    roundedRect(x, y, w, h, 4.0f);
    fillColor(Color(0.12f, 0.12f, 0.12f));
    fill();

    const float knobR = 18.0f;
    const float cy = y + h * 0.45f;
    const float spacing = w / (static_cast<float>(fNumGlobalKnobs) + 1.0f);

    for (int i = 0; i < fNumGlobalKnobs; ++i)
    {
        Knob& k = fGlobalKnobs[i];
        k.x = x + spacing * (i + 1);
        k.y = cy;
        k.radius = knobR;
        drawKnob(k);
    }
}

// ── Knob drawing ──────────────────────────────────────────────────────
void drawKnob(const Knob& k)
{
    const float startAngle = 0.75f * 3.14159f;
    const float endAngle   = 2.25f * 3.14159f;
    const float range      = endAngle - startAngle;
    const float normalized = (k.max > k.min) ? (k.value - k.min) / (k.max - k.min) : 0.0f;
    const float valueAngle = startAngle + normalized * range;

    // Track background
    beginPath();
    arc(k.x, k.y, k.radius, startAngle, endAngle, NanoVG::CCW);
    strokeColor(Palette::outline);
    strokeWidth(3.5f);
    stroke();

    // Value arc
    beginPath();
    arc(k.x, k.y, k.radius, startAngle, valueAngle, NanoVG::CCW);
    strokeColor(k.dragging ? Palette::highlight : Palette::accent);
    strokeWidth(3.5f);
    stroke();

    // Centre dot
    beginPath();
    circle(k.x, k.y, 3.5f);
    fillColor(Palette::text);
    fill();

    // Label
    fontSize(9.0f);
    fontFaceId(fFontId);
    fillColor(Palette::text);
    textAlign(ALIGN_CENTER | ALIGN_TOP);
    text(k.x, k.y + k.radius + 5.0f, k.label, nullptr);
}

